/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 /opt/homebrew/opt/python@3.14/bin/python3.14 -B -m unittest discover -s tests -v
PYTHONDONTWRITEBYTECODE=1 /opt/homebrew/opt/python@3.14/bin/python3.14 -B -c 'import lib
class L(list): pass
cases = [([], []), ([1], [1]), ([10**100, 2, 1], [10**100, 2, 1])]
for values, expected in cases:
    before = values.copy(); result = lib.validate_batch(values)
    assert result == expected and result is not values and values == before
for bad in ((), {}, iter([1]), L([1])):
    try: lib.validate_batch(bad)
    except TypeError: pass
    else: raise AssertionError((bad, \"expected TypeError\"))
for values, exc in (([1, False, 2], TypeError), ([1, -1, 2], ValueError), ([1, 0, False], ValueError)):
    before = values.copy()
    try: lib.validate_batch(values)
    except exc: pass
    else: raise AssertionError((values, exc))
    assert values == before
print(\"independent AC2 scenarios: OK\")'
shasum -a 256 _spec_inputs/0-high-level.md _spec_inputs/1-tasks.md _spec_inputs/2-spec.md _spec_inputs/3-design.md _spec_inputs/4-proposal.md lib.py tests/test_batch.py tests/test_positive_integer.py tests/test_baseline.py"

